    {
      "id": "cost-crossover-points",
      "insight": "Annotate and highlight the specific years when solar and wind LCOE crossed below the cost range of new fossil fuel generation, making these crossover moments visually prominent"
    },
    {
      "id": "capacity-acceleration",
      "insight": "Emphasize the exponential growth pattern in cumulative installed capacity for solar PV, particularly the steep acceleration after 2018, alongside the steadier but still substantial growth in onshore wind capacity"
    },
    {
      "id": "subsidy-contrast",
      "insight": "Visually contrast the persistent scale of annual fossil fuel subsidies against the declining costs of renewables, showing the divergence between public spending on incumbents and the improving economics of clean energy"
    },
    {
      "id": "battery-cost-collapse",
      "insight": "Highlight the steepness of battery storage cost decline, which alongside solar PV represents the most dramatic percentage reduction among the technologies tracked, falling from $1,100/MWh to $102/MWh"
    }
