      width: 24px; height: 2px;
      flex-shrink: 0;
    }

    /* === INSIGHT CALLOUTS === */
    .insight-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 24px;
      margin-bottom: 56px;
    }
    .insight-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px 24px;
    }
    .insight-icon {
      width: 32px; height: 32px;
      margin-bottom: 10px;
    }
    .insight-heading {
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 6px;
    }
    .insight-body {
      font-size: 0.78rem;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* === SOURCE === */
    .source-note {
      font-size: 0.72rem;
      color: var(--text-secondary);
      margin-top: 32px;
      padding-top: 20px;
      border-top: 1px solid var(--border);
    }

    /* === MENU === */
    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    /* === SKIP LINK === */
    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* === ANIMATIONS === */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fadeIn {
      from { opacity: 0; } to { opacity: 1; }
    }
    .reveal { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
      .reveal { opacity: 1; transform: none; }
    }

    /* === PRINT === */
    @media print {
      body { background: white !important; color: black !important; }
      .viz-menu { display: none; }
      .reveal { opacity: 1 !important; transform: none !important; }
      .card, .chart-card, .kpi-card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 0.75in; }

    /* === RESPONSIVE === */
    @media (max-width: 1100px) {
      .chart-grid { grid-template-columns: 1fr; }
      .kpi-strip { grid-template-columns: repeat(2, 1fr); }
      .insight-row { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 680px) {
      .kpi-strip { grid-template-columns: 1fr 1fr; }
      .insight-row { grid-template-columns: 1fr; }
      .page-wrapper { padding: 32px 16px 60px; }
    }
    @media (max-width: 375px) {
      body { overflow-x: hidden; }
      .kpi-strip { grid-template-columns: 1fr 1fr; }
      .kpi-value { font-size: 1.6rem; }
    }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Open menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <main id="main-content" role="main">
    <div class="page-wrapper">

      <!-- HEADER -->
      <section>
        <header class="page-header">
          <div class="eyebrow">Energy Transition Research</div>
          <h1>The Renewable Cost Revolution</h1>
          <p class="subtitle">
            Levelized costs of solar PV, onshore wind, and battery storage have collapsed 89–91% since 2010 — crossing below new-build fossil fuel ranges while installed capacity scaled exponentially and annual fossil fuel subsidies remained persistently high.
          </p>
        </header>
      </section>

      <!-- KPI STRIP -->
      <section aria-label="Key statistics">
        <div class="kpi-strip">
          <div class="kpi-card">
            <div class="kpi-label">Solar PV LCOE 2024</div>
            <div class="kpi-value solar" data-count="33" data-prefix="$" data-suffix="/MWh">$33/MWh</div>
            <div class="kpi-delta">↓ 91% since 2010 (from $359)</div>
          </div>
          <div class="kpi-card">
            <div class="kpi-label">Onshore Wind LCOE 2024</div>
            <div class="kpi-value wind" data-count="35" data-prefix="$" data-suffix="/MWh">$35/MWh</div>
            <div class="kpi-delta">↓ 63% since 2010 (from $95)</div>
          </div>
          <div class="kpi-card">
            <div class="kpi-label">Battery Storage LCOE 2024</div>
            <div class="kpi-value battery" data-count="102" data-prefix="$" data-suffix="/MWh">$102/MWh</div>
            <div class="kpi-delta">↓ 91% since 2010 (from $1,100)</div>
          </div>
          <div class="kpi-card">
            <div class="kpi-label">Fossil Fuel Subsidies 2024</div>
            <div class="kpi-value subsidy" data-count="550" data-prefix="$" data-suffix="B">$550B</div>
            <div class="kpi-delta neg">↑ 34% vs 2010 ($410B baseline)</div>
          </div>
        </div>
      </section>

      <!-- CHART ROW 1: LCOE + Capacity -->
      <section aria-label="LCOE trends and installed capacity">
        <div class="chart-grid">

          <!-- LCOE CHART -->
          <div class="chart-card" data-reveal>
            <div class="chart-header">
              <div class="chart-tag">Cost Trends · USD/MWh (2023 real)</div>
              <div class="chart-title">LCOE Decline vs Fossil Fuel Cost Band</div>
              <div class="chart-subtitle">Solar crosses below gas CCGT range c.2017; wind crosses below c.2016. Both now well below coal floor.</div>
            </div>
            <div class="chart-container tall" role="img" aria-label="Line chart showing LCOE decline for solar PV from $359 to $33, onshore wind from $95 to $35, and battery storage from $1100 to $102 between 2010 and 2024, with fossil fuel cost reference band overlaid showing crossover moments">
              <canvas id="lcoeChart"></canvas>
            </div>
            <div class="annotation-legend">
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--solar)"></div>
                <span>Solar PV</span>
              </div>
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--wind)"></div>
                <span>Onshore Wind</span>
              </div>
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--battery)"></div>
                <span>Battery Storage</span>
              </div>
              <div class="ann-item">
                <div class="ann-line" style="background:rgba(239,68,68,0.5); border-top:2px dashed var(--fossil)"></div>
                <span>Fossil Fuel Range (Gas + Coal)</span>
              </div>
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--solar); border:2px solid white; width:12px;height:12px"></div>
                <span>★ Crossover year</span>
              </div>
            </div>
          </div>

          <!-- CAPACITY CHART -->
          <div class="chart-card" data-reveal>
            <div class="chart-header">
              <div class="chart-tag">Installed Capacity · GW Cumulative</div>
              <div class="chart-title">Exponential Capacity Growth</div>
              <div class="chart-subtitle">Solar PV accelerates steeply after 2018; onshore wind shows steady, substantial growth throughout.</div>
            </div>
            <div class="chart-container tall" role="img" aria-label="Area chart showing cumulative solar PV capacity growing from 40 GW in 2010 to 1950 GW in 2024, and onshore wind from 178 GW to 960 GW, with solar showing exponential acceleration after 2018">
              <canvas id="capacityChart"></canvas>
            </div>
            <div class="annotation-legend">
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--solar)"></div>
                <span>Solar PV (GW)</span>
              </div>
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--wind)"></div>
                <span>Onshore Wind (GW)</span>
              </div>
            </div>
          </div>

        </div>
      </section>

      <!-- CHART ROW 2: Subsidies + Battery zoom -->
      <section aria-label="Fossil fuel subsidies and battery cost collapse">
        <div class="chart-grid">

          <!-- SUBSIDY CHART -->
          <div class="chart-card" data-reveal>
            <div class="chart-header">
              <div class="chart-tag">Annual Global Subsidies · Billion USD (nominal)</div>
              <div class="chart-title">Fossil Fuel Subsidies Remain Persistently High</div>
              <div class="chart-subtitle">Despite renewable cost collapse, public spending on fossil fuels spiked to $700B in 2022 and remains above $500B. Contrast with the rapidly improving economics of clean energy.</div>
            </div>
            <div class="chart-container" role="img" aria-label="Stacked bar chart showing annual fossil fuel subsidies from 2010 to 2024, split into consumption and production subsidies. Total ranges from $290 billion in 2020 to $700 billion in 2022, with 2024 at $550 billion">
              <canvas id="subsidyChart"></canvas>
            </div>
            <div class="annotation-legend">
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--subsidy)"></div>
                <span>Consumption Subsidies ($B)</span>
              </div>
              <div class="ann-item">
                <div class="ann-dot" style="background:var(--fossil)"></div>
                <span>Production Subsidies ($B)</span>
              </div>
            </div>
          </div>

          <!-- BATTERY COST CHART -->
          <div class="chart-card" data-reveal>
            <div class="chart-header">
              <div class="chart-tag">Battery Storage · USD/MWh (2023 real)</div>
              <div class="chart-title">Battery Cost Collapse: –91% in 14 Years</div>
              <div class="chart-subtitle">From $1,100/MWh in 2010 to $102/MWh in 2024 — the steepest proportional decline of all tracked technologies alongside solar PV.</div>
            </div>
            <div class="chart-container" role="img" aria-label="Bar chart showing battery storage LCOE declining from $1100 per MWh in 2010 to $102 per MWh in 2024, representing a 91 percent cost reduction">
              <canvas id="batteryChart"></canvas>
            </div>
          </div>

        </div>
      </section>

      <!-- INSIGHT CARDS -->
      <section aria-label="Key insights" data-reveal>
        <div class="insight-row">
          <div class="insight-card">
            <svg class="insight-icon" viewBox="0 0 32 32" fill="none" stroke="var(--solar)" stroke-width="2" stroke-linecap="round">
              <circle cx="16" cy="16" r="7"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="16" y1="26" x2="16" y2="30"/>
              <line x1="2" y1="16" x2="6" y2="16"/><line x1="26" y1="16" x2="30" y2="16"/>
              <line x1="6.3" y1="6.3" x2="9.2" y2="9.2"/><line x1="22.8" y1="22.8" x2="25.7" y2="25.7"/>
              <line x1="25.7" y1="6.3" x2="22.8" y2="9.2"/><line x1="9.2" y1="22.8" x2="6.3" y2="25.7"/>
            </svg>
            <div class="insight-heading">Solar Crossover: ~2017</div>
            <div class="insight-body">Solar PV LCOE ($72/MWh) crossed below the gas CCGT upper range (~$52–$78/MWh) around 2017 and definitively below the gas floor by 2019. By 2024, solar at $33/MWh is less than half the cheapest new-build gas plant.</div>
          </div>
          <div class="insight-card">
            <svg class="insight-icon" viewBox="0 0 32 32" fill="none" stroke="var(--wind)" stroke-width="2" stroke-linecap="round">
              <path d="M16 4 C16 4 22 10 16 16 C10 22 16 28 16 28"/>
              <path d="M16 16 L28 10"/>
              <path d="M16 16 L4 22"/>
              <circle cx="16" cy="16" r="2" fill="var(--wind)" stroke="none"/>
            </svg>
            <div class="insight-heading">Wind Crossover: ~2016</div>
            <div class="insight-body">Onshore wind reached parity with the cheapest new-build gas around 2016 at $56/MWh. By 2020 it matched the coal floor ($65/MWh). Today at $35/MWh wind is the cheapest utility-scale electricity source in most markets.</div>
          </div>
          <div class="insight-card">
            <svg class="insight-icon" viewBox="0 0 32 32" fill="none" stroke="var(--subsidy)" stroke-width="2" stroke-linecap="round">
              <rect x="4" y="14" width="6" height="14" rx="2"/>
              <rect x="13" y="8" width="6" height="20" rx="2"/>
              <rect x="22" y="18" width="6" height="10" rx="2"/>
              <line x1="2" y1="28" x2="30" y2="28"/>
            </svg>
            <div class="insight-heading">Subsidy Divergence</div>
            <div class="insight-body">Even as renewables became the cheapest power option, global fossil fuel subsidies reached a record $700B in 2022 (energy price crisis spike) and remain at $550B in 2024 — 34% above 2010 levels. The divergence between clean energy economics and incumbent spending is widening.</div>
          </div>
        </div>
      </section>

      <!-- SOURCE NOTE -->
      <section>
        <p class="source-note">
          Data: IRENA, BloombergNEF, IEA — 2023 real USD/MWh for LCOE; nominal USD for subsidies. Battery storage reflects 4-hour lithium-ion systems. Fossil fuel subsidy estimates cover direct government subsidies only. 2024 values are preliminary estimates.
        </p>
      </section>

    </div>
  </main>

  <script>
    // === MENU ===
    function toggleMenu() {
      var d = document.getElementById('vizMenuDropdown');
      if (d) d.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var d = document.getElementById('vizMenuDropdown');
        if (d) d.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var d = document.getElementById('vizMenuDropdown');
        if (d) d.classList.remove('open');
      }
    });

    // === THEME ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === SCROLL REVEAL ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) {
        if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); }
      });
    }, { threshold: 0.1 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    // === NUMBER COUNTERS ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var prefix = el.dataset.prefix || '';
        var suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1000;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1);
          var eased = 1 - Math.pow(1 - p, 3);
          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }

    // === DOWNLOAD PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2 });
        var a = document.createElement('a'); a.href = url;
        a.download = 'renewable-cost-revolution.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // === CHART DATA ===
    var years = [2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024];
    var solarLcoe   = [359,304,223,175,136,107,86,72,60,50,42,39,45,37,33];
    var windLcoe    = [95,89,82,78,72,64,56,52,48,44,41,38,42,37,35];
    var batteryLcoe = [1100,980,860,750,620,510,395,310,245,187,150,132,139,119,102];

    // Fossil fuel band interpolated to all years
    var gasLow  = [55,52.5,50,49,48,45,42,43,44,44.5,45,50,55,52.5,50];
    var gasHigh = [82,80,78,76.5,75,73.5,72,75,78,76,74,84.5,95,87.5,80];
    var coalLow = [65,64,63,61.5,60,60,60,61,62,63.5,65,70,75,72.5,70];
    var coalHigh= [105,102.5,100,99,98,96.5,95,97.5,100,105,110,120,130,125,120];

    // Combined fossil floor/ceiling
    var fossilMin = gasLow.map(function(v,i){ return Math.min(v, coalLow[i]); });
    var fossilMax = coalHigh.map(function(v,i){ return Math.max(v, gasHigh[i]); });

    var capacitySolar = [40,70,100,137,177,227,303,402,512,627,760,942,1185,1550,1950];
    var capacityWind  = [178,215,260,296,336,380,425,480,540,594,650,725,800,880,960];

    var subsidyYears  = [2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024];
    var subsidyCons   = [350,430,455,435,415,260,250,275,330,310,230,365,610,530,465];
    var subsidyProd   = [60,70,75,75,75,65,60,65,70,70,60,75,90,90,85];

    var batteryYears  = years;
    var batteryVals   = batteryLcoe;

    // === CHART MANAGER ===
    var ChartManager = {
      charts: {},
      safeInit: function(id, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts[id]) {
            try { this.charts[id].destroy(); } catch(e){}
            delete this.charts[id];
          }
          var old = document.getElementById(id);
          if (!old) return null;
          var parent = old.parentNode;
          var canvas = document.createElement('canvas');
          canvas.id = id;
          parent.replaceChild(canvas, old);
          canvas.setAttribute('role','img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label','Chart');
          var chart = new Chart(canvas, config);
          this.charts[id] = chart;
          return chart;
        } catch(err) {
          console.error('Chart init failed for ' + id, err);
          return null;
        }
      }
    };

    var chartsBuilt = false;

    function getCssVar(name) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;

      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor       = isDark ? '#EDEDED' : '#0f172a';
      var textSecondary   = isDark ? '#888888' : '#64748b';
      var gridColor       = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.06)';
      var solarColor      = getCssVar('--solar');
      var windColor       = getCssVar('--wind');
      var batteryColor    = getCssVar('--battery');
      var fossilColor     = getCssVar('--fossil');
      var subsidyColor    = getCssVar('--subsidy');

      Chart.defaults.color = textSecondary;
      Chart.defaults.font.family = 'Inter';

      // ----- LCOE CHART -----
      ChartManager.safeInit('lcoeChart', {
        type: 'line',
        data: {
          labels: years,
          datasets: [
            {
              label: 'Fossil Min (Gas)',
              data: fossilMin,
              fill: false,
              borderColor: 'transparent',
              backgroundColor: 'transparent',
              pointRadius: 0,
              borderWidth: 0,
              tension: 0.3,
              order: 10
            },
            {
              label: 'Fossil Band (Gas–Coal)',
              data: fossilMax,
              fill: '-1',
              borderColor: 'transparent',
              backgroundColor: isDark ? 'rgba(239,68,68,0.12)' : 'rgba(220,38,38,0.08)',
              pointRadius: 0,
              borderWidth: 0,
              tension: 0.3,
              order: 9
            },
            {
              label: 'Solar PV',
              data: solarLcoe,
              borderColor: solarColor,
              backgroundColor: 'transparent',
              pointRadius: function(ctx) {
                var idx = ctx.dataIndex;
                // mark crossover years: solar ~2017 (idx 7), wind ~2016 (idx 6)
                return (idx === 7) ? 8 : (idx === 0 || idx === 14 ? 5 : 3);
              },
              pointBackgroundColor: function(ctx) {
                return ctx.dataIndex === 7 ? '#ffffff' : solarColor;
              },
              pointBorderColor: solarColor,
              pointBorderWidth: 2,
              borderWidth: 2.5,
              tension: 0.35,
              order: 3
            },
            {
              label: 'Onshore Wind',
              data: windLcoe,
              borderColor: windColor,
              backgroundColor: 'transparent',
              pointRadius: function(ctx) {
                var idx = ctx.dataIndex;
                return (idx === 6) ? 8 : (idx === 0 || idx === 14 ? 5 : 3);
              },
              pointBackgroundColor: function(ctx) {
                return ctx.dataIndex === 6 ? '#ffffff' : windColor;
              },
              pointBorderColor: windColor,
              pointBorderWidth: 2,
              borderWidth: 2.5,
              tension: 0.35,
              order: 2
            },
            {
              label: 'Battery Storage',
              data: batteryLcoe,
              borderColor: batteryColor,
              backgroundColor: 'transparent',
              pointRadius: function(ctx) {
